# Is a lazy registration function present?
toplevel, _, _ = cls.__module__.partition(".")
try:
    register = self._lazy.pop(toplevel)
except KeyError:
    pass
else:
    register()
    return self.dispatch(cls)  # recurse

actions.new_string:
# Check for lazy registration in the full MRO
for mro_cls in inspect.getmro(cls):
    toplevel, _, _ = mro_cls.__module__.partition(".")
    try:
        register = self._lazy.pop(toplevel)
    except KeyError:
        continue
    else:
        register()
        return self.dispatch(cls)  # recurse after registration
